ROOT = Path(__file__).resolve().parents[1]

def plan():
    figures = []
    def add(ch, id, section, caption, note, kind='flow', **data):
        figures.append(dict(chapter=f'ch{ch}', id=id, section=section,
                            caption=caption, note=note, kind=kind, **data))
    add(1,'systems','### 4.1','मानव शरीर: प्रमुख अंग तंत्र','अंग तंत्र मिलकर आंतरिक वातावरण स्थिर रखते हैं। फेफड़े गैस विनिमय, आंत अवशोषण, वृक्क उत्सर्जन और रक्त परिवहन करता है।','map',title='Human organ systems',groups=[['Exchange','Lungs: O2 / CO2','Gut: nutrient absorption'],['Transport','Heart + blood vessels','Lymph: fluid return'],['Control + support','Nervous + endocrine','Skeleton + muscles']],footer='Systems cooperate; no organ system works in isolation.')
    add(1,'feedback','#### समस्थापन','ऋणात्मक प्रतिपुष्टि: ताप नियमन','ताप बढ़ने पर हाइपोथैलेमस पसीना और त्वचा की वाहिकाओं का फैलना सक्रिय करता है; ताप घटने पर कंपकंपी और वाहिका संकुचन होते हैं। प्रतिक्रिया विचलन को कम करती है।',title='Negative feedback: body temperature',nodes=['Temperature rises','Thermoreceptors detect change','Hypothalamus integrates','Sweating + skin vasodilation','Heat loss increases','Temperature moves toward set point'],footer='The response opposes the original change; the set point is regulated.')
    add(2,'skeleton','### 4.1','मानव कंकाल: अक्षीय एवं उपांगी भाग','Skull = खोपड़ी; Vertebral column = कशेरुक दंड; Rib cage = वक्ष पिंजर; Pelvis = श्रोणि। वयस्क का सामान्य मॉडल 206 अस्थियां दिखाता है: अक्षीय 80, उपांगी 126।','raster',title='Human skeleton')
    add(2,'joint','### 4.2','साइनोवियल संधि: उपास्थि, गुहा एवं कैप्सूल','Articular cartilage = संधीय उपास्थि; Synovial fluid = साइनोवियल द्रव; Ligament = स्नायु। उपास्थि घर्षण घटाती है, द्रव स्नेहन देता है और स्नायु अस्थि को अस्थि से जोड़ता है।','raster',title='Synovial joint')
    add(2,'sarcomere','### 4.3','सार्कोमियर: Z रेखा से Z रेखा तक','Actin = पतला तंतु; Myosin = मोटा तंतु। I band में केवल पतले तंतु, H zone में केवल मोटे तंतु और A band में मोटे तंतु की पूरी लंबाई होती है।','raster',title='Sarcomere structure')
    add(2,'sliding','### 4.3','स्लाइडिंग फिलामेंट: तंतु सरकते हैं','संकुचन में Z रेखाएं निकट आती हैं; I band और H zone घटते हैं, A band स्थिर रहता है। एक्टिन और मायोसिन की लंबाई नहीं घटती।','sliding',title='Sliding filaments: relaxed versus contracted',footer='Filaments retain their lengths. Overlap increases; the A band stays constant.')
    add(3,'digestion','## भाग 4:','मानव पाचन तंत्र: आहार नाल और सहायक अंग','Mouth = मुख; Oesophagus = ग्रासनली; Stomach = आमाशय; Small intestine = छोटी आंत। यकृत पित्त बनाता है; पित्ताशय उसे संग्रहित करता है। अग्न्याशय का रस ग्रहणी में पहुंचता है।','existing',source='biology_digestion.png',title='Human digestive system')
    add(3,'villus','### 4.5','आंत्र विलस: रक्त एवं लसीका में अवशोषण','Villus = रसांकुर; Lacteal = लसीका केशिका। अधिकांश ग्लूकोज और अमीनो अम्ल रक्त केशिकाओं में; लंबी शृंखला वसा के काइलोमाइक्रॉन लैक्टियल में जाते हैं। माइक्रोविलस कोशिका सतह पर बहुत छोटे उभार हैं।','raster',title='Intestinal villus')
    add(3,'enzymes','### 4.4','पाचक एंजाइम: स्थान, सब्सट्रेट एवं उत्पाद','पेप्सिन आमाशय में प्रोटीन पाचन शुरू करता है। अग्न्याशयी एंजाइम छोटी आंत में कार्य करते हैं; ब्रश बॉर्डर एंजाइम अंतिम चरण पूरा करते हैं। पित्त एंजाइम नहीं है।','table',title='Digestive enzymes: where and what',headers=['Site / enzyme','Substrate','Main products'],rows=[['Mouth: salivary amylase','Starch','Shorter carbohydrates'],['Stomach: pepsin','Proteins','Peptides'],['Small gut: pancreatic proteases','Proteins / peptides','Smaller peptides'],['Small gut: pancreatic lipase','Triglycerides','Fatty acids + monoglycerides'],['Brush border: disaccharidases','Disaccharides','Monosaccharides']],footer='Peptidases complete peptide digestion. Bile emulsifies fat; it is not an enzyme.')
    add(3,'secretions','### 4.3','यकृत और अग्न्याशय के पाचक स्राव','पित्त वसा को इमल्सीफाई करता है। अग्न्याशयी बाइकार्बोनेट अम्लीय काइम को उदासीन करता है और एंजाइम पाचन करते हैं।','map',title='Secretions reaching the duodenum',groups=[['Liver → gallbladder','Bile production / storage','Fat emulsification'],['Pancreatic acini','Digestive enzymes','Carbohydrates, fats, proteins'],['Pancreatic ducts','Bicarbonate-rich fluid','Neutralises acidic chyme']],footer='Separate sources cooperate in the duodenum; bile contains no digestive enzymes.')
    add(4,'respiratory','### 4.1','मानव श्वसन मार्ग: नासिका से वायुकोष तक','Trachea = श्वासनली; Bronchi = श्वसनी; Bronchioles = श्वसनीकाएं; Alveoli = वायुकोष। गैस विनिमय वायुकोष एवं आसपास की केशिकाओं में होता है।','raster',title='Human respiratory tract')
    add(4,'alveoli','### 4.4','वायुकोष एवं केशिका: O2 और CO2 विनिमय','O2 वायुकोष से रक्त और CO2 रक्त से वायुकोष में आंशिक दाब प्रवणता के अनुसार विसरित होती है। पतली श्वसन झिल्ली और विशाल सतह विनिमय में सहायक हैं।','raster',title='Alveolar gas exchange')
    add(4,'breathing','### 4.2','अंतःश्वसन और उच्छ्वसन की तुलना','शांत अंतःश्वसन में डायफ्राम संकुचित होकर नीचे जाता है; वक्ष आयतन बढ़ता और वायुकोषीय दाब घटता है। शांत उच्छ्वसन मुख्यतः निष्क्रिय प्रत्यास्थ वापसी है।','table',title='Quiet breathing: pressure drives airflow',headers=['Feature','Inhalation','Exhalation'],rows=[['Diaphragm','Contracts; descends','Relaxes; rises'],['Thoracic volume','Increases','Decreases'],['Alveolar pressure','Below atmospheric','Above atmospheric'],['Air movement','Into lungs','Out of lungs'],['Main mechanism','Active muscle contraction','Passive elastic recoil']],footer='Forced expiration recruits muscles. Intrapleural and alveolar pressures differ.')
    add(5,'heart','### 4. मानव','हृदय: चार कक्ष एवं कपाट','Right atrium = दायां आलिंद; Right ventricle = दायां निलय। चित्र में शरीर का दायां भाग दर्शक के बाएं है। त्रिकपर्दी कपाट दाएं तथा माइट्रल बाएं भाग में है; बाएं निलय की दीवार मोटी है।','raster',title='Human heart: chambers and valves')
    add(5,'circulation','### 4. मानव','दोहरा परिसंचरण: फुफ्फुसीय और दैहिक पथ','फुफ्फुसीय धमनी अपेक्षाकृत ऑक्सीजन-रहित और फुफ्फुसीय शिराएं ऑक्सीजनयुक्त रक्त ले जाती हैं। धमनी हृदय से दूर, शिरा हृदय की ओर रक्त ले जाती है।',title='Double circulation: follow the blood',nodes=['Body tissues','Venae cavae → right atrium','Right ventricle','Pulmonary arteries → lungs','Pulmonary veins → left atrium','Left ventricle → aorta → body'],footer='Pulmonary and systemic circuits are in series. Artery does not mean oxygen-rich.')
    add(5,'cardiac_cycle','### 6. कार्डियक','कार्डियक चक्र: दाब एवं कपाट की अवस्थाएं','कपाट दाब अंतर से खुलते और बंद होते हैं। प्रथम हृदय ध्वनि AV कपाटों तथा द्वितीय ध्वनि अर्धचंद्राकार कपाटों के बंद होने से जुड़ी है।','table',title='Cardiac cycle: ventricular phases',headers=['Phase','AV valves','Semilunar valves'],rows=[['Ventricular filling','Open','Closed'],['Isovolumetric contraction','Closed','Closed'],['Ventricular ejection','Closed','Open'],['Isovolumetric relaxation','Closed','Closed']],footer='S1: AV valve closure. S2: semilunar valve closure. Pressure differences drive valves.')
    add(5,'blood','### 1. रक्त','रक्त के घटक: प्लाज्मा एवं निर्मित तत्व','RBC = लाल रक्त कोशिका; WBC = श्वेत रक्त कोशिका; Platelet = प्लेटलेट। RBC गैस परिवहन, WBC प्रतिरक्षा और प्लेटलेट रक्तस्तंभन में भाग लेते हैं। प्लेटलेट कोशिका खंड हैं।','raster',title='Blood components')
    add(6,'lymph','### 3. लसीकाभ','लसीका तंत्र: वाहिकाएं और प्रमुख अंग','Bone marrow और Thymus प्राथमिक लसीकाभ अंग हैं; लसीका गांठ, प्लीहा और MALT द्वितीयक हैं। प्लीहा रक्त को और लसीका गांठ लसीका को छानती है।','raster',title='Lymphatic vessels and organs')
    add(6,'fluid_return','### 2. लसीका','ऊतक द्रव से शिरापरक रक्त तक','केशिकाओं से निकले तरल और प्रोटीन का अतिरिक्त भाग लसीका मार्ग से शिरापरक रक्त में लौटता है। लसीका वाहिकाओं के कपाट और पेशीय गति प्रवाह में सहायक हैं।',title='Tissue fluid returns through lymph',nodes=['Blood capillaries: filtration','Interstitial fluid surrounds cells','Excess fluid enters lymph capillaries','Collecting vessels + nodes','Lymphatic trunks and ducts','Venous blood near neck'],footer='Lymph returns fluid and proteins; it is not pumped by a separate heart.')
    add(7,'urinary','### 1. वृक्क','मानव मूत्र तंत्र: वृक्क से मूत्रमार्ग तक','Kidney = वृक्क; Ureter = मूत्रवाहिनी; Urinary bladder = मूत्राशय; Urethra = मूत्रमार्ग। मूत्रवाहिनी और मूत्रमार्ग अलग संरचनाएं हैं।','raster',title='Human urinary system')
    add(7,'nephron','### 2. नेफ्रॉन','नेफ्रॉन: निस्यंदन एवं नलिकीय मार्ग','Glomerulus = केशिकागुच्छ; Bowman capsule = बोमन कैप्सूल; PCT = समीपस्थ कुंडलित नलिका; DCT = दूरस्थ कुंडलित नलिका। निस्यंद PCT → हेनले लूप → DCT → संग्रह नलिका से गुजरता है।','raster',title='Nephron structure')
    add(7,'urine_formation','### 3. मूत्र','मूत्र निर्माण के तीन मुख्य चरण','निस्यंदन: रक्त से कैप्सूल में; पुनरवशोषण: नलिका से रक्त में; स्रवण: रक्त से नलिका में। सामान्य निस्यंद में रक्त कोशिकाएं और अधिकांश बड़े प्रोटीन नहीं होते।','transport',title='Filtration, reabsorption and secretion',footer='Excretion = filtration − reabsorption + secretion. Directions refer to solute movement.')
    add(7,'countercurrent','### 4. प्रतिधारा','प्रतिधारा तंत्र: मज्जा की परासरण प्रवणता','अवरोही भुजा जल के लिए पारगम्य है। मोटी आरोही भुजा जल के लिए अपारगम्य होकर लवण बाहर भेजती है। वासा रेक्टा प्रवणता बचाती है; ADH संग्रह नलिका की जल पारगम्यता बढ़ाता है।','countercurrent',title='Countercurrent mechanism: medullary gradient',footer='Loop: multiplier. Vasa recta: exchanger. Urea also contributes to the gradient.')
    add(8,'neuron','### 1. न्यूरॉन','न्यूरॉन: डेंड्राइट, कोशिकाकाय एवं अक्षतंतु','Dendrite = डेंड्राइट; Soma = कोशिकाकाय; Axon = अक्षतंतु; Myelin = माइलिन। माइलिनयुक्त तंतु में नोड्स ऑफ रैनवियर पर आवेग पुनः बनता है; हर न्यूरॉन माइलिनयुक्त नहीं है।','raster',title='Neuron structure')
    add(8,'brain','### 4. मानव','मानव मस्तिष्क: प्रमुख भागों का मध्य अनुदैर्ध्य दृश्य','Cerebrum = प्रमस्तिष्क; Thalamus = थैलेमस; Hypothalamus = हाइपोथैलेमस; Cerebellum = अनुमस्तिष्क; Medulla = मेडुला। अनुमस्तिष्क गति और संतुलन में, मेडुला अनेक स्वायत्त कार्यों में भाग लेता है।','raster',title='Human brain: midsagittal view')
    add(8,'reflex','### 5. मेरुरज्जु','प्रतिवर्ती चाप: संवेदना से क्रिया तक','त्वचा के पीड़ाग्राही से संवेदी न्यूरॉन संकेत मेरुरज्जु पहुंचाता है; इंटरन्यूरॉन मोटर न्यूरॉन से जोड़ता है और पेशी प्रतिक्रिया करती है। यह बहुसिनेप्सीय withdrawal reflex है; सभी प्रतिवर्त ऐसे नहीं हैं।',title='Withdrawal reflex: a polysynaptic arc',nodes=['Pain receptor in skin','Sensory neuron','Spinal cord interneuron','Motor neuron','Skeletal muscle contracts','Limb withdraws from stimulus'],footer='The brain also receives information; the spinal response can begin before conscious awareness.')
    add(8,'synapse','### 3. सिनेप्स','रासायनिक सिनेप्स: एक न्यूरॉन से दूसरे तक','आवेग से Ca2+ प्रवेश होता है और पुटिकाएं न्यूरोट्रांसमीटर छोड़ती हैं। वे पश्चसिनेप्सीय रिसेप्टर से जुड़ते हैं; प्रभाव उत्तेजक या निरोधक हो सकता है।','raster',title='Chemical synapse')
    add(9,'eye','### 1. मानव','मानव नेत्र: लेंस, रेटिना एवं दृष्टि तंत्रिका','Cornea = कॉर्निया; Iris = परितारिका; Retina = दृष्टिपटल; Optic nerve = दृष्टि तंत्रिका। प्रकाश कॉर्निया और लेंस से रेटिना तक पहुंचता है; नेत्र एक सरल कैमरा मॉडल से अधिक जटिल है।','raster',title='Human eye: sectional view')
    add(9,'ear','### 3. मानव','मानव कर्ण: श्रवण एवं संतुलन के भाग','Pinna = कर्णपल्लव; Eardrum = कर्णपटह; Ossicles = कर्ण अस्थिकाएं; Cochlea = कॉक्लिया। कॉक्लिया श्रवण और vestibular apparatus संतुलन में भाग लेता है।','raster',title='Human ear: hearing and balance')
    add(9,'visual_pathway','### 1. मानव','दृष्टि पथ: आंशिक क्रॉसिंग एवं दृश्य क्षेत्र','दृष्टि कियाज्मा में नासिका-पक्ष रेटिना के तंतु क्रॉस करते हैं; कनपटी-पक्ष के तंतु उसी ओर रहते हैं। प्रत्येक प्रमस्तिष्क गोलार्ध विपरीत दृश्य क्षेत्र की सूचना प्राप्त करता है।','visual',title='Visual pathway: partial crossing at the chiasm',footer='Nasal retinal fibres cross. Temporal retinal fibres remain ipsilateral.')
    add(9,'skin','### 5. घ्राण','त्वचा के संवेदी रिसेप्टर: प्रतिनिधि मॉडल','Free nerve endings = मुक्त तंत्रिका अंत; Meissner corpuscle = हल्के स्पर्श का रिसेप्टर; Pacinian corpuscle = कंपन/गहरे दाब का रिसेप्टर। रिसेप्टर की स्थिति त्वचा के प्रकार पर निर्भर करती है।','raster',title='Skin sensory receptors')
    add(10,'glands','#### 2. ग्रंथियों','प्रमुख अंतःस्रावी ग्रंथियां: अवस्थिति','Pituitary = पीयूष; Thyroid = थायरॉइड; Adrenal = अधिवृक्क; Pancreas = अग्न्याशय। थायरॉइड के पीछे पैराथायरॉइड और वृक्कों के ऊपर अधिवृक्क होते हैं। जनन ग्रंथियां अलग पुरुष/स्त्री इनसेट में हैं।','raster',title='Major endocrine glands')
    add(10,'hormone_feedback','#### 6. थायरॉइड','थायरॉइड हार्मोन: अक्ष एवं ऋणात्मक प्रतिपुष्टि','हाइपोथैलेमस TRH → पीयूष TSH → थायरॉइड T3/T4। T3/T4 बढ़ने पर ऊपर के केंद्रों का उत्तेजन कम होता है।','feedback',title='Hypothalamus–pituitary–thyroid axis',footer='Thyroid hormone inhibits upstream TRH and TSH release: negative feedback.')
    add(10,'hormone_action','#### 12. हार्मोन','हार्मोन क्रिया: झिल्ली बनाम अंतःकोशिकीय रिसेप्टर','पेप्टाइड हार्मोन सामान्यतः झिल्ली रिसेप्टर और संकेत मार्ग से कार्य करते हैं। स्टेरॉयड हार्मोन अंतःकोशिकीय रिसेप्टर से जीन अभिव्यक्ति बदलते हैं; थायरॉइड हार्मोन भी नाभिकीय रिसेप्टर से कार्य करते हैं।','table',title='Two broad routes of hormone action',headers=['Feature','Peptide hormones','Steroid hormones'],rows=[['Receptor','Usually cell surface','Intracellular'],['Membrane passage','Do not freely diffuse','Diffuse across membrane'],['Main signalling','Second messengers / kinases','Gene transcription changes'],['Example','Insulin','Cortisol']],footer='These are broad models; receptor and signalling details vary by hormone.')
    add(11,'male','#### 1. नर','नर जनन तंत्र: शुक्राणु एवं स्राव का मार्ग','Testis = वृषण; Epididymis = अधिवृषण; Vas deferens = शुक्रवाहिनी; Prostate = प्रोस्टेट। शुक्राणु वृषण में बनकर अधिवृषण में परिपक्व होते हैं; मूत्रमार्ग अंतिम साझा मार्ग है।','raster',title='Male reproductive system')
    add(11,'female','#### 2. मादा','मादा जनन तंत्र: अंडाशय, अंडवाहिनी एवं गर्भाशय','Ovary = अंडाशय; Uterine tube = अंडवाहिनी; Uterus = गर्भाशय; Cervix = गर्भाशय ग्रीवा। सामान्य निषेचन अंडवाहिनी की ampulla में और आरोपण गर्भाशय के एंडोमेट्रियम में होता है।','raster',title='Female reproductive system')
    add(11,'gametogenesis','#### 3. युग्मकजनन','शुक्रजनन और अंडजनन: विभाजन एवं उत्पाद','शुक्रजनन में एक प्राथमिक शुक्राणुकोशिका से चार शुक्राणु बन सकते हैं। अंडजनन में असमान विभाजन से एक बड़ा कार्यात्मक अंडाणु और ध्रुवीय पिंड बनते हैं; meiosis-II निषेचन के बाद पूरा होता है।','table',title='Gametogenesis: compare the two pathways',headers=['Stage','Spermatogenesis','Oogenesis'],rows=[['Starting meiotic cell','Primary spermatocyte (2n)','Primary oocyte (2n)'],['After meiosis I','Two secondary cells (n)','Secondary oocyte + polar body'],['After meiosis II','Four spermatids (n)','Ovum + polar body'],['Cytoplasm division','Approximately equal','Unequal'],['Completion','Followed by sperm maturation','Meiosis II triggered by fertilisation']],footer='DNA replicates before meiosis I. Haploid does not mean each chromosome is unreplicated.')
    add(11,'implantation','#### 5. निषेचन','निषेचन से आरोपण: प्रारंभिक विकास','जाइगोट की cleavage से मोरुला और फिर ब्लास्टोसिस्ट बनता है। कुल आकार शुरू में बहुत नहीं बढ़ता; कोशिकाओं की संख्या बढ़ती है। ब्लास्टोसिस्ट एंडोमेट्रियम में आरोपित होता है।',title='Fertilisation to implantation',nodes=['Fertilisation in uterine tube','Zygote','Cleavage: 2 → 4 → 8 cells','Morula','Blastocyst reaches uterus','Implantation in endometrium'],footer='Stage sequence is schematic; early cleavage divides the cytoplasm into smaller cells.')
    add(12,'contraception','#### 3. जन्म','गर्भनिरोधक विधियां: क्रियाविधि की तुलना','कंडोम गर्भधारण और अनेक STI का जोखिम घटाते हैं। हार्मोनल विधियां और IUD मुख्यतः गर्भधारण रोकने के लिए हैं; STI से सुरक्षा नहीं देते। यह शैक्षिक तुलना है।','table',title='Contraception: mechanisms differ',headers=['Method','Main mechanism','STI risk reduction'],rows=[['Condom','Barrier to sperm','Yes; not complete protection'],['Hormonal methods','Suppress ovulation / alter mucus','No'],['Copper IUD','Impairs sperm function','No'],['Vasectomy','Interrupts vas deferens','No'],['Tubal surgery','Interrupts uterine tubes','No']],footer='Choice and suitability need clinical assessment; methods are not equally effective.')
    add(12,'art','#### 6. बंध्यता','IVF: शरीर के बाहर निषेचन से भ्रूण अंतरण','IVF में अंडाणु और शुक्राणु प्रयोगशाला में मिलते हैं; भ्रूण गर्भाशय में अंतरण किया जाता है। ICSI में एक शुक्राणु अंडाणु में प्रवेश कराया जाता है। सफलता निश्चित नहीं है।',title='IVF: an assisted reproduction pathway',nodes=['Clinical assessment','Ovarian stimulation + monitoring','Oocyte retrieval + sperm preparation','Laboratory fertilisation (IVF / ICSI)','Embryo culture','Embryo transfer to uterus'],footer='Implantation is a later biological event; transfer does not guarantee pregnancy.')
    add(13,'food_plate','#### 6. संतुलित','विविध संतुलित आहार: खाद्य समूह','अनाज, दालें, सब्जियां, फल, दूध या उपयुक्त विकल्प, मेवे और सीमित तेल पोषण में योगदान देते हैं। अनुपात आयु, गतिविधि और जरूरत के अनुसार बदलता है।','plate',title='Balanced diet: variety across food groups',footer='Illustrative food groups, not a fixed serving prescription or calorie plan.')
    add(13,'nutrients','#### 1. पोषक','पोषक तत्व: मुख्य कार्य एवं स्रोत','कार्बोहाइड्रेट और वसा ऊर्जा, प्रोटीन वृद्धि और मरम्मत में योगदान देते हैं। विटामिन और खनिज ऊर्जा नहीं देते; अनेक नियामक कार्य करते हैं।','table',title='Nutrients: roles and representative sources',headers=['Nutrient','Main roles','Examples of sources'],rows=[['Carbohydrate','Energy','Grains, millets, tubers'],['Protein','Growth; repair; enzymes','Pulses, dairy, eggs'],['Fat','Energy; membranes','Oils, nuts, seeds'],['Vitamins / minerals','Metabolic regulation','Diverse fruits + vegetables'],['Fibre / water','Gut function / hydration','Whole grains; safe water']],footer='Foods contain multiple nutrients; examples are not exclusive sources.')
    add(14,'deficiencies','#### 1. विटामिनों','मुख्य हीनता संबंध: विटामिन एवं खनिज','Vitamin A की कमी रतौंधी, C की कमी स्कर्वी, D की कमी रिकेट्स/ऑस्टियोमलेशिया और आयोडीन की कमी थायरॉइड विकार से जुड़ी है। हर एनीमिया आयरन की कमी से नहीं होता।','table',title='Selected nutrient deficiencies',headers=['Nutrient','Deficiency association','Key function'],rows=[['Vitamin A','Night blindness','Vision; epithelial health'],['Vitamin C','Scurvy','Collagen synthesis'],['Vitamin D','Rickets / osteomalacia','Calcium homeostasis'],['Iron','Iron-deficiency anaemia','Haemoglobin'],['Iodine','Iodine-deficiency disorders','Thyroid hormone synthesis']],footer='Associations support revision; symptoms alone do not establish a diagnosis.')
    add(14,'malnutrition','#### 5. प्रोटीन','क्वाशिओरकर और मरास्मस: प्रमुख भेद','मरास्मस में गंभीर क्षीणता और क्वाशिओरकर में द्विपक्षीय पोषणजन्य शोफ प्रमुख है। दोनों जटिल गंभीर कुपोषण के रूप हैं; उन्हें केवल एक पोषक तत्व की कमी से समझना अधूरा है।','table',title='Severe malnutrition: two clinical patterns',headers=['Feature','Marasmus','Kwashiorkor'],rows=[['Key pattern','Marked wasting','Bilateral nutritional oedema'],['Fat / muscle','Severely depleted','Wasting may be masked'],['Skin / hair','Changes can occur','Changes often prominent'],['Assessment','Growth + clinical assessment','Growth + oedema assessment']],footer='Patterns can overlap. Oedema can conceal low body mass; prompt clinical care is needed.')
    add(15,'infection_chain','#### 4. संक्रमण','संक्रमण की शृंखला: छह कड़ियां','रोगजनक → भंडार → निकास द्वार → संचरण → प्रवेश द्वार → संवेदनशील मेजबान। किसी कड़ी पर प्रभावी रोकथाम संक्रमण का जोखिम घटा सकती है।',title='Chain of infection: six links',nodes=['Infectious agent','Reservoir','Portal of exit','Mode of transmission','Portal of entry','Susceptible host'],footer='Hand hygiene, sanitation, barriers and vaccination interrupt different links.')
    add(15,'transmission','#### 4. संक्रमण','संक्रमण मार्ग एवं रोकथाम के उदाहरण','श्वसन, मल-मुख, रक्त/यौन और वाहक जनित संचरण अलग मार्ग हैं। एक रोग एक से अधिक मार्ग से फैल सकता है; सावधानियां रोग एवं परिस्थिति पर निर्भर हैं।','table',title='Transmission routes and prevention',headers=['Route','Example','Prevention focus'],rows=[['Respiratory','Influenza / TB','Ventilation; disease-specific measures'],['Faecal–oral','Cholera','Safe water; sanitation'],['Blood / sexual','HIV','Sterile equipment; barriers'],['Vector-borne','Malaria','Mosquito control; bite prevention'],['Contact','Some skin infections','Hygiene; avoid shared items']],footer='Routes can overlap. Prevention requires measures suited to the pathogen and setting.')
    add(16,'virus_replication','### 2. विषाणु','विषाणु प्रतिकृति: मेजबान कोशिका की भूमिका','विषाणु मेजबान कोशिका की व्यवस्था पर निर्भर हैं। attachment, entry, uncoating, synthesis, assembly और release का यह सामान्य मॉडल है; सभी विषाणुओं में विवरण समान नहीं हैं।',title='General animal-virus replication cycle',nodes=['Attachment to host receptor','Entry into host cell','Uncoating of viral genome','Genome replication + protein synthesis','Assembly of new virions','Release: budding or cell lysis'],footer='Different viral families use different enzymes, compartments and release mechanisms.')
    add(16,'hiv','### 3. ह्यूमन','HIV: CD4 कोशिका और प्रतिरक्षा ह्रास','HIV RNA से reverse transcriptase DNA बनाता है; viral DNA मेजबान जीनोम में एकीकृत हो सकता है। CD4 T कोशिकाओं की क्षति प्रतिरक्षा कमजोर करती है। ART प्रतिकृति को दबाता है।',title='HIV in a CD4 T cell',nodes=['HIV binds CD4 + co-receptor','Viral entry','RNA → DNA: reverse transcription','Viral DNA integrates into host DNA','Viral RNA + proteins are produced','New virions assemble and bud'],footer='HIV infection and AIDS are not synonyms; sustained treatment suppresses viral replication.')
    add(16,'mosquito','### 6. आर्बो','डेंगू: मानव-मच्छर संचरण चक्र','संक्रमित Aedes मच्छर के काटने से डेंगू फैलता है। मच्छर संक्रमित व्यक्ति से रक्त भोजन लेकर विषाणु प्राप्त कर सकता है; उसके भीतर विकास के बाद संचरण संभव होता है।','cycle',title='Dengue: human–Aedes transmission',nodes=['Infected human','Mosquito takes blood meal','Virus multiplies in mosquito','Infectious mosquito bites','Another human becomes infected'],footer='Mosquito-borne cycle; routine casual contact is not the usual route.')
    add(17,'malaria','### 2. प्रोटोजोआ','मलेरिया: मानव एवं मच्छर में जीवन चक्र','संक्रमित मादा Anopheles स्पोरोजोइट देती है; यकृत चरण के बाद लाल रक्त कोशिकाएं संक्रमित होती हैं। गैमीटोसायट मच्छर में पहुंचकर लैंगिक चरण शुरू करते हैं।',title='Malaria: simplified Plasmodium life cycle',nodes=['Mosquito injects sporozoites','Liver stage in human','Merozoites infect red blood cells','Some parasites become gametocytes','Mosquito ingests gametocytes','Sexual stages → sporozoites in mosquito'],footer='Asexual stages occur in humans; sexual reproduction occurs in the mosquito.')
    add(17,'pathogens','### 1. प्रमुख','रोगजनक पहचान: प्रमुख समूह एवं उदाहरण','बैक्टीरिया प्रोकैरियोट, कवक यूकैरियोट, प्रोटोजोआ एककोशिकीय यूकैरियोट और हेल्मिन्थ बहुकोशिकीय परजीवी हैं। उपचार रोगजनक के प्रकार पर निर्भर है।','table',title='Pathogen groups: representative examples',headers=['Group','Example','Associated disease'],rows=[['Bacterium','Mycobacterium tuberculosis','Tuberculosis'],['Fungus','Dermatophytes','Ringworm'],['Protozoan','Plasmodium','Malaria'],['Helminth','Ascaris lumbricoides','Ascariasis']],footer='Ringworm is fungal; its name does not mean a worm causes it.')
    add(17,'amr','### 5. रोगाणुरोधी','एंटीबायोटिक प्रतिरोध: चयन एवं प्रसार','औषधि संवेदनशील जीवाणुओं को रोकती है; प्रतिरोधी जीवाणु बचकर बढ़ सकते हैं। उत्परिवर्तन या जीन स्थानांतरण प्रतिरोध दे सकते हैं; मानव शरीर स्वयं एंटीबायोटिक-प्रतिरोधी नहीं बनता।','selection',title='Antibiotic resistance: selection among bacteria',footer='Antibiotics select resistant variants; resistance genes can also transfer between bacteria.')
    add(18,'immunity','### 1. प्रतिरक्षा','सहज और उपार्जित प्रतिरक्षा का मानचित्र','सहज प्रतिरक्षा में बाधाएं और त्वरित प्रतिक्रियाएं हैं। उपार्जित प्रतिरक्षा में B और T कोशिकाएं विशिष्ट पहचान एवं स्मृति बनाती हैं; दोनों प्रणालियां सहयोग करती हैं।','map',title='Immunity: cooperating defence systems',groups=[['Innate','Skin + mucosal barriers','Phagocytes + complement'],['Adaptive: B cells','Plasma cells: antibodies','Memory B cells'],['Adaptive: T cells','Helper / cytotoxic T cells','Memory T cells']],footer='Innate signals help activate adaptive responses; the two systems interact.')
    add(18,'antibody','### 3. प्रतिरक्षी','प्रतिरक्षी: Y आकार एवं बंधन स्थल','एक IgG मॉडल में दो heavy और दो light chains हैं। variable regions प्रतिजन पहचानते हैं; Fc क्षेत्र प्रतिरक्षा प्रभावक क्रियाओं से जुड़ा है। सभी immunoglobulin इसी इकाई की समान व्यवस्था में नहीं होते।','raster',title='Antibody structure: an IgG model')
    add(18,'immune_response','### 5. सक्रिय','प्राथमिक एवं द्वितीयक प्रतिरक्षा प्रतिक्रिया','उसी प्रतिजन की दोबारा पहचान पर स्मृति कोशिकाएं प्रायः तेज एवं अधिक प्रभावी प्रतिक्रिया देती हैं। वक्र योजनाबद्ध है; अलग टीकों और रोगजनकों में प्रतिक्रिया भिन्न होती है।','response',title='Primary and secondary antibody responses',footer='Schematic curves, not measured titres. Memory supports a faster response to the same antigen.')
    add(19,'glucose','### 2. मधुमेह','रक्त ग्लूकोज: इंसुलिन और ग्लूकागॉन','ऊंचे ग्लूकोज पर beta cells इंसुलिन, कम ग्लूकोज पर alpha cells ग्लूकागॉन स्रवित करते हैं। इंसुलिन संग्रह/उपयोग बढ़ाता है; ग्लूकागॉन यकृत से ग्लूकोज उपलब्ध कराता है।','table',title='Blood glucose regulation: opposing responses',headers=['Trigger','Hormone / source','Main response'],rows=[['Blood glucose rises','Insulin: beta cells','Uptake in responsive tissues; storage'],['Blood glucose falls','Glucagon: alpha cells','Liver glycogen breakdown; gluconeogenesis']],footer='Type 1 diabetes: insulin deficiency. Type 2: insulin resistance with progressive dysfunction.')
    add(19,'risks','### 1. असंक्रामक','असंक्रामक रोग: जोखिम एवं सुरक्षा कारक','तंबाकू, हानिकारक मदिरा उपयोग, असंतुलित आहार और कम गतिविधि अनेक NCD जोखिम बढ़ाते हैं। आनुवंशिकी, आयु एवं सामाजिक परिस्थितियां भी भूमिका निभाती हैं; जोखिम रोग की निश्चित भविष्यवाणी नहीं है।','map',title='Noncommunicable disease: shared risk factors',groups=[['Behavioural','Tobacco; harmful alcohol use','Diet; physical inactivity'],['Biological','Raised blood pressure / glucose','Lipids; excess adiposity'],['Protective actions','Healthy food; regular activity','Screening + appropriate care']],footer='Risk is probabilistic; genes, age, environment and access to care also matter.')
    add(20,'chromosomes','### 1. मानव','गुणसूत्रीय विकार: संख्यात्मक तुलना','Down syndrome सामान्यतः trisomy 21, Turner का एक सामान्य मॉडल 45,X और Klinefelter का 47,XXY है। मोज़ेक एवं अन्य रूप भी होते हैं; चित्र निदान का विकल्प नहीं है।','table',title='Chromosomal disorders: common karyotype models',headers=['Condition','Common karyotype','Change'],rows=[['Down syndrome','47, +21','Extra chromosome 21'],['Turner syndrome','45, X','One X chromosome'],['Klinefelter syndrome','47, XXY','Extra X in XXY model']],footer='These are common models; mosaicism and structural variants also occur.')
    add(20,'inheritance','### 4. ऑटोसोमल','ऑटोसोमल अप्रभावी वंशागति: वाहक माता-पिता','Aa × Aa में प्रत्येक गर्भ के लिए AA 1/4, Aa 1/2 और aa 1/4 की संभावना है। वाहक प्रायः प्रभावित नहीं होते; पिछले बच्चे का परिणाम अगले गर्भ की संभावना नहीं बदलता।','punnett',title='Autosomal recessive inheritance: Aa × Aa',footer='Each pregnancy is an independent event: 25% AA, 50% Aa, 25% aa.')
    add(21,'hygiene','### 2. जल','जनस्वास्थ्य: जल, हाथ एवं अपशिष्ट स्वच्छता','सुरक्षित पेयजल, साबुन से हाथ धोना, सुरक्षित खाद्य तैयारी और उचित कचरा निपटान संक्रमण की अलग कड़ियां तोड़ते हैं। जैव-चिकित्सा अपशिष्ट के लिए अलग विनियमित व्यवस्था जरूरी है।','map',title='Hygiene: interrupt exposure at several points',groups=[['Water + sanitation','Protect source; treat water','Safe toilets; prevent contamination'],['Hands + food','Soap and water','Cook, store and handle safely'],['Waste','Segregate at source','Safe collection + disposal']],footer='Biomedical waste requires regulated handling; do not mix sharps with household waste.')
    add(21,'cpr','### 6. प्राथमिक','वयस्क के अचानक गिरने पर: CPR एवं AED पथ','स्थान सुरक्षित करें। वयस्क अचेत और सामान्य सांस न ले रहा हो (केवल हांफना सामान्य सांस नहीं) तो आपातकालीन सहायता बुलाएं और AED मंगाएं। अप्रशिक्षित प्रत्यक्षदर्शी छाती के बीच 100–120/मिनट दबाव दें, लगभग 5–6 सेमी गहराई और पूरी वापसी रखें। AED के निर्देश मानें; विश्लेषण/शॉक में कोई न छुए। यह अचानक वयस्क cardiac arrest हेतु hands-only सार है; बच्चों और डूबने में rescue breaths विशेष महत्वपूर्ण हैं।',title='Adult sudden collapse: hands-only CPR + AED',nodes=['Check scene safety','Unresponsive + not breathing normally?','Call emergency help; send for AED','Chest centre: 100–120 compressions/min','AED arrives: follow voice prompts','Resume CPR promptly; continue until help'],footer='Adult sudden cardiac arrest summary. Follow dispatcher instructions; CPR training adds vital skills.')
    add(22,'recovery','### 4. व्यसन','निर्भरता और सुधार: सहायता का मार्ग','व्यसन उपचार योग्य स्वास्थ्य समस्या है। withdrawal का जोखिम पदार्थ और उपयोग पर निर्भर है; मदिरा या sedative withdrawal गंभीर हो सकता है। चिकित्सकीय आकलन, मनोसामाजिक समर्थन और नियमित अनुवर्तन मदद करते हैं।',title='Dependence and recovery: a support pathway',nodes=['Recognise harmful use / dependence','Seek confidential professional assessment','Assess withdrawal and medical risks','Individual treatment + counselling','Family / peer support with consent','Follow-up; respond early to recurrence'],footer='Recovery varies between people. Severe withdrawal needs urgent medical assessment.')
    add(23,'programmes','### 4. प्रमुख','स्वास्थ्य कार्यक्रम: उद्देश्य का मानचित्र','NHM स्वास्थ्य सेवाओं की पहुंच और गुणवत्ता, UIP टीकाकरण, NTEP टीबी रोकथाम/देखभाल और ABDM सहमति-आधारित डिजिटल स्वास्थ्य व्यवस्था पर केंद्रित हैं। लाभ, पात्रता और स्थानीय सेवाएं वर्तमान आधिकारिक सूचना से जांचें।','table',title='Health programmes: purpose map',headers=['Programme','Core purpose','Who / what it supports'],rows=[['NHM','Accessible, equitable quality care','Community health services'],['UIP','Vaccine-preventable disease control','Children and pregnant women'],['NTEP','TB prevention, diagnosis and care','People at risk / affected by TB'],['ABDM / ABHA','Interoperable digital health records','People + health-care ecosystem']],footer='Purpose overview verified October 2026; check current official rules for eligibility and benefits.')
    add(24,'revision','### 1. मानव','मानव शरीर और स्वास्थ्य: समग्र पुनरावृत्ति','प्रत्येक समूह से संरचना, कार्य और एक नियमन या रोग उदाहरण जोड़ें। पाचन, श्वसन, परिसंचरण एवं उत्सर्जन मिलकर पदार्थ विनिमय और समस्थापन बनाए रखते हैं।','map',title='Biology II: connect structure, function and health',groups=[['Physiology','Exchange + transport','Control + homeostasis'],['Nutrition + defence','Nutrients + deficiency','Infection + immunity'],['Health + prevention','Inheritance + disease risk','Hygiene + public health']],footer='Revision prompt: explain one structure, one mechanism and one clinical connection per branch.')
    # The raster tool rejected reproductive anatomy; retain accurate native plates.
    for f in figures:
        if f['id'] == 'male':
            f['kind'] = 'male_anatomy'
            f['title'] = 'Male reproductive tract: internal organs'
            f['footer'] = 'Schematic organ pathway; sperm production occurs in the testes.'
            f['note'] = 'Testis = वृषण; Epididymis = अधिवृषण; Vas deferens = शुक्रवाहिनी; Prostate = प्रोस्टेट। शुक्राणु वृषण में बनकर अधिवृषण में परिपक्व होते हैं; शुक्रवाहिनी से स्खलन वाहिनी और फिर मूत्रमार्ग तक पहुंचते हैं। यह आंतरिक अंगों का योजनाबद्ध मॉडल है।'
        elif f['id'] == 'female':
            f['kind'] = 'female_anatomy'
            f['footer'] = 'Uterine tubes open near the ovaries; they are not directly attached to them.'
    assert len(figures) == 64, len(figures)
    return figures

if __name__ == '__main__':
    book = json.loads((ROOT/'assets/content/vigyansetu/vigyansetu_book6.json').read_text(encoding='utf-8'))
    figures = plan()
    for f in figures:
        c = next(c for c in book['chapters'] if c['id'] == f['chapter'])
        matches = [b['value'].splitlines()[0] for b in c['content'] if b['value'].startswith(f['section'])]
        assert len(matches) == 1, (f['id'], matches)
        f['anchor'] = matches[0]
    (ROOT/'artifacts/biology_book2_figure_briefs.json').write_text(json.dumps(figures,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Prepared {len(figures)} mixed-media briefs across 24 chapters')
